const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs');
(async()=>{fs.mkdirSync('evidence',{recursive:true});const b=await chromium.launch();let errors=[];
for(const width of [320,390,1280]){const p=await b.newPage({viewport:{width,height:844},isMobile:width<500,hasTouch:width<500});p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=400&&!r.url().includes('favicon'))errors.push(r.status()+' '+r.url())});await p.goto('http://127.0.0.1:8765/wingspan/',{waitUntil:'networkidle'});
assert.match(await p.locator('#advice h2').innerText(),/Уточни/);assert.equal(await p.locator('#quickStock').isVisible(),false);assert.equal(await p.locator('#strategyPanel details').count(),2);
await p.screenshot({path:'evidence/home-'+width+'.png',fullPage:true});
await p.locator('#advice button').click();await p.locator('#stockConfirmed').check();for(const label of ['Зерно','Черви','Яйца']){await p.locator('#quickStock button').filter({hasText:label}).click();await p.getByRole('button',{name:'Увеличить '+label,exact:true}).click()}
await p.locator('.nav [data-tab="guide"]').click();assert.doesNotMatch(await p.locator('#advice h2').innerText(),/Уточни/);await p.locator('#alternativeDetails summary').click();await p.locator('#longDetails summary').click();
assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'home overflow '+width);
await p.locator('#quickSearch').click();await p.locator('#dbQuery').fill('American Coot');await p.waitForFunction(()=>document.querySelectorAll('#dbList .dbrow').length===1);await p.locator('[data-view="cards"]').click();assert.equal(await p.locator('.atlas-card').count(),1);assert.match(await p.locator('.card-power').innerText(),/When activated/);await p.locator('#dbQuery').fill('');await p.locator('[data-kind="bonus"]').click();await p.locator('#dbQuery').fill('Anatomist');await p.locator('#dbList button').click();await p.locator('.nav [data-tab="birds"]').click();assert.match(await p.locator('#quickGoals').innerText(),/Anatomist/);
await p.locator('.nav [data-tab="catalog"]').click();await p.locator('[data-kind="birds"]').click();await p.locator('#dbQuery').fill('Raven');await p.locator('#dbList .dbrow').first().waitFor();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'catalog overflow '+width);
if(width===390)await p.screenshot({path:'evidence/cards.png',fullPage:true});
await p.reload({waitUntil:'networkidle'});assert.equal(await p.locator('[data-view="cards"]').getAttribute('aria-pressed'),'true');await p.locator('.nav [data-tab="birds"]').click();assert.match(await p.locator('#quickGoals').innerText(),/Anatomist/);
for(const tab of ['birds','game','score']){await p.locator('.nav [data-tab="'+tab+'"]').click();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,tab+' overflow '+width)}
await p.close()}await b.close();assert.deepEqual(errors,[]);console.log('Strategy browser acceptance PASS')})().catch(e=>{console.error(e);process.exitCode=1});
